-- ExamFlow institution server: database schema for SAP HANA 2.0 / HANA Cloud
-- Schema version 2. Run it connected to the EMPTY database (or schema) made for ExamFlow,
-- as its owner or an admin. Safe to run twice. Then give the ExamFlow user the rights listed in DATABASES.md.

-- Run with hdbsql, "#" ends each statement:  hdbsql -n HOST:PORT -u ADMIN -c "#" -mI hana.sql

-- ── step 1 ──
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'meta'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "meta" ("k" NVARCHAR(191) NOT NULL, "v" NCLOB, PRIMARY KEY ("k"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'docs'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "docs" ("col" NVARCHAR(64) NOT NULL, "id" NVARCHAR(300) NOT NULL, "data" NCLOB NOT NULL, "created" BIGINT NOT NULL, "updated" BIGINT NOT NULL, f_examToken NVARCHAR(255), f_teacherUid NVARCHAR(255), f_switchCode NVARCHAR(255), PRIMARY KEY ("col", "id"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'users'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "users" ("uid" NVARCHAR(191) NOT NULL, "email" NVARCHAR(320) NOT NULL, "name" NVARCHAR(1000), "pass_hash" NVARCHAR(1000), "source" NVARCHAR(32) NOT NULL, "oidc_sub" NVARCHAR(1000), "created" BIGINT NOT NULL, "disabled" INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY ("uid"), UNIQUE ("email"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'codes'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "codes" ("code_hash" NVARCHAR(191) NOT NULL, "email" NVARCHAR(1000) NOT NULL, "purpose" NVARCHAR(32) NOT NULL, "created" BIGINT NOT NULL, "expires" BIGINT NOT NULL, "used" BIGINT, PRIMARY KEY ("code_hash"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'logins'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "logins" ("token_hash" NVARCHAR(191) NOT NULL, "uid" NVARCHAR(191) NOT NULL, "created" BIGINT NOT NULL, "expires" BIGINT NOT NULL, PRIMARY KEY ("token_hash"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'oidc_state'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "oidc_state" ("state" NVARCHAR(191) NOT NULL, "nonce" NVARCHAR(1000) NOT NULL, "verifier" NVARCHAR(1000) NOT NULL, "created" BIGINT NOT NULL, PRIMARY KEY ("state"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'allowlist'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "allowlist" ("teacher_id" NVARCHAR(191) NOT NULL, "email" NVARCHAR(320) NOT NULL, "name" NVARCHAR(1000), "version" INTEGER NOT NULL, PRIMARY KEY ("teacher_id"), UNIQUE ("email"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'allowlist_history'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "allowlist_history" ("n" BIGINT GENERATED BY DEFAULT AS IDENTITY, "t" BIGINT NOT NULL, "package_id" NVARCHAR(1000), "package_version" NVARCHAR(1000), "list_version" INTEGER, "added" INTEGER, "removed" INTEGER, "total" INTEGER, PRIMARY KEY ("n"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'audit'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "audit" ("n" BIGINT GENERATED BY DEFAULT AS IDENTITY, "t" BIGINT NOT NULL, "actor" NVARCHAR(1000), "action" NVARCHAR(1000) NOT NULL, "target" NCLOB, "result" NVARCHAR(1000) NOT NULL, "detail" NCLOB, PRIMARY KEY ("n"))'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM INDEXES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND INDEX_NAME = 'DOCS_EXAMTOKEN'; IF :cnt = 0 THEN EXEC 'CREATE INDEX docs_examToken ON "docs" ("col", f_examToken)'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM INDEXES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND INDEX_NAME = 'DOCS_TEACHERUID'; IF :cnt = 0 THEN EXEC 'CREATE INDEX docs_teacherUid ON "docs" ("col", f_teacherUid)'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM INDEXES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND INDEX_NAME = 'DOCS_SWITCHCODE'; IF :cnt = 0 THEN EXEC 'CREATE INDEX docs_switchCode ON "docs" ("col", f_switchCode)'; END IF; END
#
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM INDEXES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND INDEX_NAME = 'DOCS_CREATED'; IF :cnt = 0 THEN EXEC 'CREATE INDEX docs_created ON "docs" ("col", "created")'; END IF; END
#
-- append-only protection for the audit log (audit_no_update)
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TRIGGERS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TRIGGER_NAME = 'AUDIT_NO_UPDATE'; IF :cnt = 0 THEN EXEC 'CREATE TRIGGER audit_no_update BEFORE UPDATE ON "audit" FOR EACH ROW BEGIN SIGNAL SQL_ERROR_CODE 10001 SET MESSAGE_TEXT = ''the audit log is append-only''; END'; END IF; END
#
-- append-only protection for the audit log (audit_no_delete)
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TRIGGERS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TRIGGER_NAME = 'AUDIT_NO_DELETE'; IF :cnt = 0 THEN EXEC 'CREATE TRIGGER audit_no_delete BEFORE DELETE ON "audit" FOR EACH ROW BEGIN SIGNAL SQL_ERROR_CODE 10001 SET MESSAGE_TEXT = ''the audit log is append-only''; END'; END IF; END
#

-- ── step 2 ──
DO BEGIN DECLARE cnt INT; SELECT COUNT(*) INTO cnt FROM TABLES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'inbox'; IF :cnt = 0 THEN EXEC 'CREATE COLUMN TABLE "inbox" ("msg_id" NVARCHAR(64) NOT NULL, "email" NVARCHAR(254) NOT NULL, "delivered_at" BIGINT, "read_at" BIGINT, "archived_at" BIGINT, PRIMARY KEY ("msg_id", "email"))'; END IF; END
#

-- record which schema version this database has
UPSERT "meta" ("k", "v") VALUES ('schema_version', '2') WITH PRIMARY KEY
#

